WITH monthly AS (SELECT substr(o.order_date,1,7) month, SUM(oi.quantity*oi.unit_price*(1-oi.discount)) revenue FROM orders o JOIN order_items oi USING(order_id) WHERE o.order_status='completed' GROUP BY 1) SELECT month,revenue,LAG(revenue) OVER(ORDER BY month) prior_month_revenue,ROUND(100.0*(revenue-LAG(revenue) OVER(ORDER BY month))/LAG(revenue) OVER(ORDER BY month),2) mom_growth_pct FROM monthly;
